// 1. 实现 ParkSearchCache 接口（用 SharedPreferences）
class _DemoSearchCache implements ParkSearchCache {
  Future<SharedPreferences> get _prefs => SharedPreferences.getInstance();

  Future<List<String>> loadHistory(String scope) async {
    final prefs = await _prefs;
    return prefs.getStringList('search_history_$scope') ?? [];
  }

  Future<void> saveHistory(String scope, String keyword) async {
    final prefs = await _prefs;
    final list = (prefs.getStringList('search_history_$scope') ?? []);
    list.remove(keyword);
    list.insert(0, keyword);
    await prefs.setStringList('search_history_$scope', list.take(20).toList());
  }

  Future<void> removeHistory(String scope, String keyword) async {
    final prefs = await _prefs;
    final list = (prefs.getStringList('search_history_$scope') ?? []);
    list.remove(keyword);
    await prefs.setStringList('search_history_$scope', list);
  }

  Future<void> clearHistory(String scope) async {
    final prefs = await _prefs;
    await prefs.remove('search_history_$scope');
  }
}

