    String btnText = '获取验证码';
    bool isLoading = false;
    int countdown = 0;

    void startCountdown() {
      countdown = 60;
      btnText = '60s';
      Timer.periodic(const Duration(seconds: 1), (t) {
        setState(() {
          countdown--;
          btnText = countdown <= 0 ? '重新获取' : '${countdown}s';
          if (countdown <= 0) {
            t.cancel();
          }
        });
      });
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        ParkSearch(
          hintText: '请输入手机号',
          actionText: btnText,
          loading: isLoading,
          onSubmitted: (v) {
            if (isLoading || countdown > 0) return;
            setState(() {
              isLoading = true;
              btnText = '发送中...';
            });
            Future.delayed(const Duration(seconds: 3), () {
              setState(() => isLoading = false);
              startCountdown();
            });
          },
        ),
      ],
    );
  },
)

